package com.wizzadrds.theworldremembers.voice; import java.util.*; public final class VoiceScheduler{private final int capacity;private final PriorityQueue<VoiceJob> q=new PriorityQueue<>(Comparator.comparing(VoiceJob::priority).reversed().thenComparingLong(VoiceJob::createdTick));private final Set<UUID> active=new HashSet<>();public VoiceScheduler(int capacity){if(capacity<1)throw new IllegalArgumentException();this.capacity=capacity;}public boolean submit(VoiceJob j){if(active.contains(j.npcId()))return false;if(q.size()>=capacity){VoiceJob lowest=q.stream().min(Comparator.comparing(VoiceJob::priority).thenComparingLong(VoiceJob::createdTick)).orElse(null);if(lowest!=null&&j.priority().ordinal()<=lowest.priority().ordinal())return false;if(lowest!=null)q.remove(lowest);}q.add(j);return true;}public VoiceJob startNext(){var j=q.poll();if(j!=null)active.add(j.npcId());return j;}public void finish(UUID id){active.remove(id);}public int queued(){return q.size();}}
